return {["scripts/actions/spells/black/choke.lua"]={["Path"]="scripts/actions/spells/black/choke.lua",["SHA256"]="fa8e3ac7bdc782064b0b88f169f6ea1cea6e98c859e394fe9bff17e6feab97d5",["Text"]="-----------------------------------\n-- Spell: Choke\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enfeebling.useEnfeeblingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/comet.lua"]={["Path"]="scripts/actions/spells/black/comet.lua",["SHA256"]="f93737cd9dc1bb3f14d674e47dbe55eea1eb6347041c008a9ab7c14155ac2155",["Text"]="-----------------------------------\n-- Spell: Comet\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    -- TODO: Code succesive spell use enhancement. Method still undecided.\n    return xi.spells.damage.useDamageSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/cryohelix.lua"]={["Path"]="scripts/actions/spells/black/cryohelix.lua",["SHA256"]="af16a5ed50ca2cca0340890c447e587ff985dde4aef4d7f989eef6bf0835d862",["Text"]="-----------------------------------\n-- Spell: Cryohelix\n-- Deals ice damage that gradually reduces a target's HP.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local damage = xi.spells.damage.useDamageSpell(caster, target, spell) -- Gets nuke power and sets messages.\n\n    -- Can't apply if absorbed or nullified.\n    if damage > 0 then\n        local power    = utils.clamp(damage, 0, 9999)\n        local duration = xi.spells.enfeebling.calculateDuration(caster, target, spell:getID(), xi.effect.HELIX, xi.skill.ELEMENTAL_MAGIC)\n\n        target:addStatusEffect(xi.effect.HELIX, { power = power, duration = duration, origin = caster, tick = 10, tier = 1 })\n    end\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/cryohelix_ii.lua"]={["Path"]="scripts/actions/spells/black/cryohelix_ii.lua",["SHA256"]="0dc6329c6316728432fa7f4e9bfd01d2909786bf8629a39b52b3d8572a5ca222",["Text"]="-----------------------------------\n-- Spell: Cryohelix II\n-- Deals ice damage that gradually reduces a target's HP.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local damage = xi.spells.damage.useDamageSpell(caster, target, spell) -- Gets nuke power and sets messages.\n\n    -- Can't apply if absorbed or nullified.\n    if damage > 0 then\n        local power    = utils.clamp(damage, 0, 9999)\n        local duration = xi.spells.enfeebling.calculateDuration(caster, target, spell:getID(), xi.effect.HELIX, xi.skill.ELEMENTAL_MAGIC)\n\n        target:addStatusEffect(xi.effect.HELIX, { power = power, duration = duration, origin = caster, tick = 10, tier = 2 })\n    end\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/curse.lua"]={["Path"]="scripts/actions/spells/black/curse.lua",["SHA256"]="54ba00c40427c41d9b6c286fced1d38b5e3c3a989f7869722604c3f959ef33ff",["Text"]="-----------------------------------\n-- Spell: Curse\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enfeebling.useEnfeeblingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/death.lua"]={["Path"]="scripts/actions/spells/black/death.lua",["SHA256"]="9c9b420441e4140ca22477497e58e54870dedf23a28590a4faae4b8e3607f8d1",["Text"]="-----------------------------------\n-- Spell: Death\n-- Has a chance to insta-kill the target. Ineffective against undead or notorious monsters.\n-- (Player only) Consumes all MP no matter what.\n-- (Player only) If Death fails to knock out the target, it will instead deal darkness damage.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    spell:setFlag(xi.magic.spellFlag.IGNORE_SHADOWS)\n\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    -- Player spell.\n    if caster:isPC() then\n        local instaDeath = false\n        local result     = 0\n\n        -- Insta-death calculations.\n        if\n            not target:isUndead() and\n            not target:isNM() and\n            not target:hasStatusEffect(xi.effect.MAGIC_SHIELD)\n        then\n            local params =\n            {\n                magicalElement = xi.element.DARK,\n                skillType      = xi.skill.DARK_MAGIC,\n                spellGroup     = xi.magic.spellGroup.BLACK,\n            }\n\n            local resistRate = xi.combat.magicHitRate.calculateResistRate(caster, target, params)\n\n            if resistRate == 1 then\n                instaDeath = true\n            end\n        end\n\n        if instaDeath then\n            target:setHP(0)\n        else\n            spell:setMsg(xi.msg.basic.MAGIC_DMG)\n            result = xi.spells.damage.useDamageSpell(caster, target, spell)\n        end\n\n        -- Handle MP comsumption. It bypasses \"conserve MP\" and any other form of mp reduction.\n        caster:setMP(0)\n\n        return result\n\n    -- Not-player spell.\n    else\n        if math.randomInt(1, 100) <= target:getMod(xi.mod.DEATHRES) then\n            spell:setModifier(xi.msg.actionModifier.RESIST) -- Resist!\n            spell:setMsg(xi.msg.basic.MAGIC_NO_EFFECT)\n        else\n            target:setHP(0)\n        end\n\n        return 0\n    end\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/dispel.lua"]={["Path"]="scripts/actions/spells/black/dispel.lua",["SHA256"]="d383320740624419a9c4b0847341fbc05fdcda7d3f4bf4527ce57ffe5b0a22b9",["Text"]="-----------------------------------\n-- Spell: Dispel\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enfeebling.useEnfeeblingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/dispelga.lua"]={["Path"]="scripts/actions/spells/black/dispelga.lua",["SHA256"]="bf76463972a3de74314179e2be577073628706741cfeac92d2ca0fb7f545a4dd",["Text"]="-----------------------------------\n-- Spell: Dispelga\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enfeebling.useEnfeeblingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/distract.lua"]={["Path"]="scripts/actions/spells/black/distract.lua",["SHA256"]="b69a3e77fc5d0a2eab55dd6be94e7d2660136b07ca85477b0f23c4cda15d7244",["Text"]="-----------------------------------\n-- Spell: Distract\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enfeebling.useEnfeeblingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/distract_ii.lua"]={["Path"]