n\n    if target:addStatusEffect(effect, { power = potency, duration = 180, origin = caster }) then\n        spell:setMsg(xi.msg.basic.MAGIC_GAIN_EFFECT)\n    else\n        spell:setMsg(xi.msg.basic.MAGIC_NO_EFFECT)\n    end\n\n    return effect\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/escape.lua"]={["Path"]="scripts/actions/spells/black/escape.lua",["SHA256"]="677cb0b2e37406eceaea62947780d1c4ca2b8d8cfefdd8379e2b2cfd289de37b",["Text"]="-----------------------------------\n-- Spell: Escape\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enhancing.useTeleportSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/fira.lua"]={["Path"]="scripts/actions/spells/black/fira.lua",["SHA256"]="3757153e380b58d4361a202751211b5c6432673104d92e6ff9a770993b5bfb73",["Text"]="-----------------------------------\n-- Spell: Fira\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.damage.useDamageSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/fira_ii.lua"]={["Path"]="scripts/actions/spells/black/fira_ii.lua",["SHA256"]="918e57828589fc022abcf526a29f47fe333aa01265750f9bd4d49c2cd23ce6bf",["Text"]="-----------------------------------\n-- Spell: Fira II\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.damage.useDamageSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/f